	/** 
	 * jumpstart the process by instantiating2 BusinessUnit
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		businessUnitId = BusinessUnitService.getBusinessUnitInstance()
		.createBusinessUnit( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		BusinessUnitService.getBusinessUnitInstance()
				.createBusinessUnit( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.businessUnitSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for BusinessUnit : " + successValue.getBusinessUnitId());
							  if (successValue.getBusinessUnitId().equals(businessUnitId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfBusinessUnitList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("BusinessUnit test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on businessUnit consumed")
					);
			subscriber.businessUnitSubscribe( businessUnitId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for BusinessUnit : " + successValue.getBusinessUnitId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfBusinessUnitList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on businessUnit for businessUnitId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a BusinessUnit. 
	 */
	protected BusinessUnit read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created BusinessUnit" );

		BusinessUnit entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read BusinessUnit with primary key" );
		msg.append( businessUnitId );
		
		BusinessUnitFetchOneSummary fetchOneSummary = new BusinessUnitFetchOneSummary( businessUnitId );

		try {
			entity = BusinessUnitService.getBusinessUnitInstance().getBusinessUnit( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found BusinessUnit " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a BusinessUnit.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a BusinessUnit." );

		StringBuilder msg = new StringBuilder( "Failed to update a BusinessUnit : " );        
		BusinessUnit entity = read();
		UpdateBusinessUnitCommand command = generateUpdateCommand();
		command.setBusinessUnitId(entity.getBusinessUnitId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created BusinessUnit." );

			// for use later on...
			businessUnitId = entity.getBusinessUnitId();

			BusinessUnitService proxy = BusinessUnitService.getBusinessUnitInstance();  

			proxy.updateBusinessUnit( command ).get();

			LOGGER.info( "-- Successfully saved BusinessUnit - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + businessUnitId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a BusinessUnit.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created BusinessUnit." );

		BusinessUnit entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read BusinessUnit with id " + businessUnitId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read BusinessUnit with id " + businessUnitId );

			throw e;
		}

		try{
			BusinessUnitService.getBusinessUnitInstance().delete( new DeleteBusinessUnitCommand( entity.getBusinessUnitId() ) ).get();
			LOGGER.info( "-- Successfully deleted BusinessUnit with id " + businessUnitId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete BusinessUnit with id " + businessUnitId );

			throw e;
		}
	}

	/**
	 * get all BusinessUnits.
	 */
	protected List<BusinessUnit> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of BusinessUnits:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all BusinessUnit : " );        
		List<BusinessUnit> collection  = new ArrayList<>();

		try {
			// call the static get method on the BusinessUnitService
			collection = BusinessUnitService.getBusinessUnitInstance().getAllBusinessUnit();
			assertNotNull( collection, "An Empty collection of BusinessUnit was incorrectly returned.");
			
			// Now print out the values
			BusinessUnit entity = null;            
			Iterator<BusinessUnit> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getBusinessUnitId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

